import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, add, mul, floor, sin, dot, fract } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // --------------------------------------------------------------------------
  // Helpers
  // --------------------------------------------------------------------------
  const toRgb = (hex) => {
    const i = parseInt(hex.replace('#', ''), 16);
    return [(i >> 16 & 255) / 255, (i >> 8 & 255) / 255, (i & 255) / 255];
  };

  const setMaterialOpacity = (obj, value) => {
    obj.traverse((child) => {
      if (child.isMesh && child.material && 'opacity' in child.material) {
        child.material.transparent = true;
        child.material.opacity = value;
      }
    });
  };

  // --------------------------------------------------------------------------
  // Extract spec data
  // --------------------------------------------------------------------------
  const colors = config.colors ?? config?.visualSpec?.colors ?? {};
  const typography = config.typography ?? config?.visualSpec?.typography ?? {};
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // --------------------------------------------------------------------------
  // Root group
  // --------------------------------------------------------------------------
  const root = new Group();

  // --------------------------------------------------------------------------
  // Backdrop plane with vertical gradient
  // --------------------------------------------------------------------------
  const bgGeometry = new PlaneGeometry(7, 5.5);
  const bgMaterial = new MeshBasicNodeMaterial();

  const bgColorStart = vec3(...toRgb(colors.background ?? '#0b0b10'));
  const bgColorEnd = vec3(...toRgb(colors.surface ?? '#14141a'));

  // simple grain using fract(sin(dot(uv, vec2(...))) * 43758.5453)
  const grainScale = 120.0;
  const grain = fract(sin(dot(mul(uv(), grainScale), vec3(12.9898, 78.233, 0))) * 43758.5453);
  const grainFactor = mul(grain, 0.015); // 1.5% monochrome grain

  const gradient = mix(bgColorStart, bgColorEnd, uv().y);
  bgMaterial.colorNode = add(gradient, grainFactor);
  bgMaterial.transparent = false;

  const bgMesh = new Mesh(bgGeometry, bgMaterial);
  bgMesh.position.set(0, 0, 0);
  root.add(bgMesh);

  // --------------------------------------------------------------------------
  // Text creation
  // --------------------------------------------------------------------------
  const textGroup = new Group();
  const leftX = -3.1;
  const textColor = colors.paper ?? '#e8ecf2';

  // Kicker
  const kickerSpec = typography.kicker ?? {};
  const kicker = ctx.fontAtlas.createText('NOVA ATELIER / JOURNAL', {
    fontSize: kickerSpec.fontSize ?? 18,
    color: textColor,
    align: 'left',
    letterSpacingPx: (kickerSpec.letterSpacing ?? 0.12) * (kickerSpec.fontSize ?? 18),
  });
  const kickerContainer = new Group();
  kickerContainer.add(kicker);
  kickerContainer.position.set(leftX, 1.7, 0);
  kickerContainer.position.y += 0.4; // start offset for rise‑in
  setMaterialOpacity(kickerContainer, 0);
  textGroup.add(kickerContainer);

  // Hero line 1
  const heroSpec = typography.hero ?? {};
  const heroLine1 = ctx.fontAtlas.createText('PRECISION IS', {
    fontSize: heroSpec.fontSize ?? 124,
    color: textColor,
    align: 'left',
    letterSpacingPx: (heroSpec.letterSpacing ?? -0.015) * (heroSpec.fontSize ?? 124),
  });
  const hero1Container = new Group();
  hero1Container.add(heroLine1);
  hero1Container.position.set(leftX, 0.9, 0);
  hero1Container.position.y += 0.4;
  setMaterialOpacity(hero1Container, 0);
  textGroup.add(hero1Container);

  // Hero line 2
  const heroLine2 = ctx.fontAtlas.createText('A HABIT.', {
    fontSize: heroSpec.fontSize ?? 124,
    color: textColor,
    align: 'left',
    letterSpacingPx: (heroSpec.letterSpacing ?? -0.015) * (heroSpec.fontSize ?? 124),
  });
  const hero2Container = new Group();
  hero2Container.add(heroLine2);
  hero2Container.position.set(leftX, 0.25, 0);
  hero2Container.position.y += 0.4;
  setMaterialOpacity(hero2Container, 0);
  textGroup.add(hero2Container);

  // Body paragraph
  const bodySpec = typography.body ?? {};
  const body = ctx.fontAtlas.createText(
    'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
    {
      fontSize: bodySpec.fontSize ?? 26,
      color: textColor,
      align: 'left',
      maxWidthPx: 4.5 * 100, // rough conversion, not critical
      letterSpacingPx: (bodySpec.letterSpacing ?? 0) * (bodySpec.fontSize ?? 26),
    }
  );
  const bodyContainer = new Group();
  bodyContainer.add(body);
  bodyContainer.position.set(leftX, -0.8, 0);
  bodyContainer.position.y += 0.4;
  setMaterialOpacity(bodyContainer, 0);
  textGroup.add(bodyContainer);

  // Caption
  const captionSpec = typography.caption ?? {};
  const caption = ctx.fontAtlas.createText('ISSUE 12 / JULY 2026', {
    fontSize: captionSpec.fontSize ?? 18,
    color: textColor,
    align: 'left',
    letterSpacingPx: (captionSpec.letterSpacing ?? 0.08) * (captionSpec.fontSize ?? 18),
  });
  const captionContainer = new Group();
  captionContainer.add(caption);
  captionContainer.position.set(leftX, -1.9, 0);
  captionContainer.position.y += 0.4;
  setMaterialOpacity(captionContainer, 0);
  textGroup.add(captionContainer);

  root.add(textGroup);

  // --------------------------------------------------------------------------
  // Underline rule (accent)
  // --------------------------------------------------------------------------
  const ruleGeometry = new PlaneGeometry(2.2, 0.05);
  const ruleMaterial = new MeshStandardNodeMaterial();
  const accentRgb = toRgb(colors.accent ?? '#ff2a38');
  ruleMaterial.emissiveNode = vec3(...accentRgb);
  ruleMaterial.emissiveIntensity = 1.2;
  const ruleMesh = new Mesh(ruleGeometry, ruleMaterial);
  ruleMesh.position.set(leftX, -0.15, 0.01); // slightly in front
  ruleMesh.scale.set(0, 1, 1); // start collapsed
  root.add(ruleMesh);

  // --------------------------------------------------------------------------
  // GSAP timeline for entrance and rule animation
  // --------------------------------------------------------------------------
  const timeline = gsap.timeline({ defaults: { ease: 'cubic-bezier(0.215,0.61,0.355,1)', duration: 0.7 } });

  const blocks = [
    { obj: kickerContainer, targetY: 1.7 },
    { obj: hero1Container, targetY: 0.9 },
    { obj: hero2Container, targetY: 0.25 },
    { obj: bodyContainer, targetY: -0.8 },
    { obj: captionContainer, targetY: -1.9 },
  ];

  blocks.forEach((block, i) => {
    timeline.to(
      block.obj.position,
      { y: block.targetY, duration: 0.7 },
      i * 0.08
    );
    timeline.to(
      block.obj,
      {
        onUpdate() {
          setMaterialOpacity(block.obj, block.obj.material ? block.obj.material.opacity : 1);
        },
        opacity: 1,
        duration: 0.7,
        immediateRender: false,
      },
      i * 0.08
    );
  });

  // After hero lines settle, animate underline rule scaleX
  timeline.to(
    ruleMesh.scale,
    {
      x: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    '+=0.1' // after previous animations
  );

  timeline.play();

  // --------------------------------------------------------------------------
  // Cleanup
  // --------------------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timeline.kill();
    bgGeometry.dispose();
    bgMaterial.dispose();
    ruleGeometry.dispose();
    ruleMaterial.dispose();
    // Dispose any textures that may have been attached (none in this spec)
    // Dispose text meshes if needed (fontAtlas may reuse, safe to traverse)
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  return root;
}
